UPDATE `farm`
user_id = #{userId}, farm_name = #{farmName}, img_url = #{imgUrl}, contact_phone = #{contactPhone}, address = #{address}, total_area = #{totalArea}, area_unit = #{areaUnit}, longitude = #{longitude}, latitude = #{latitude}, status = #{status}, remark = #{remark},
WHERE id = #{id}

mapper.select:
SELECT FROM `farm` f LEFT JOIN `user` u ON u.id = f.user_id
AND f.farm_name LIKE CONCAT('%', #{farmName}, '%')
AND f.farm_code LIKE CONCAT('%', #{farmCode}, '%')
AND f.user_id = #{userId}
AND f.status = #{status}
ORDER BY f.id DESC

SELECT COUNT(1)
FROM `farm`
WHERE user_id = #{userId}
  AND farm_code = #{farmCode}

    AND id != #{excludeId}

SELECT COUNT(1)
FROM `farm`
WHERE farm_code = #{farmCode}

    AND id != #{excludeId}
